INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'A1', 'mcq', 'email', 'What course is being offered?', to_jsonb(ARRAY['Excel','Word','PowerPoint','Accounting']::text[]), 'Excel', 'The email says "We have a new Excel course."', (SELECT id FROM passage2_1)),
  ('reading', 'A1', 'mcq', 'email', 'Which room is the training in?', to_jsonb(ARRAY['Room 5','Room 2','Room 10','Room 3']::text[]), 'Room 5', 'The email states "The training room is Room 5."', (SELECT id FROM passage2_1)),
  ('reading', 'A1', 'mcq', 'email', 'Who should staff contact to join the course?', to_jsonb(ARRAY['Anna','Karim','HR','the manager']::text[]), 'Anna', 'The email says "Please tell Anna if you want to join"; Karim only signed the email.', (SELECT id FROM passage2_1));
