    ('Expense Policy Update', 'Expense Policy Update
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'A2', 'mcq', 'general', 'How many days do staff have to submit an expense claim?', to_jsonb(ARRAY['14 days','20 days','7 days','30 days']::text[]), '14 days', 'The policy says staff must submit claims "within 14 days of the purchase."', (SELECT id FROM passage2_2)),
  ('reading', 'A2', 'mcq', 'general', 'When is a receipt required?', to_jsonb(ARRAY['For amounts over €20','For all claims','For amounts under €20','Only for travel claims']::text[]), 'For amounts over €20', 'The policy states a receipt is needed "for any amount over €20" and that claims under €20 do not need one.', (SELECT id FROM passage2_2)),
  ('reading', 'A2', 'mcq', 'general', 'Who should staff contact if they have questions about their claim?', to_jsonb(ARRAY['Sophie in Finance','the HR manager','the finance team''s general email','the office manager']::text[]), 'Sophie in Finance', 'The policy says "If you have questions, contact Sophie in Finance before you submit your claim."', (SELECT id FROM passage2_2));
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag) VALUES
    ('IT Security Notice', 'IT Security Notice
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'A2', 'mcq', 'general', 'How often must staff change their password?', to_jsonb(ARRAY['Every 60 days','Every 30 days','Every 8 days','Every year']::text[]), 'Every 60 days', 'The notice says "Please change your computer password every 60 days."', (SELECT id FROM passage2_3)),
  ('reading', 'A2', 'mcq', 'general', 'What should staff do if they forget their password?', to_jsonb(ARRAY['Call the IT Help Desk','Write it on paper','Ask another staff member','Send an email to IT']::text[]), 'Call the IT Help Desk', 'The notice says "call the IT Help Desk at extension 204," while it says not to write passwords down or share them.', (SELECT id FROM passage2_3)),
  ('reading', 'A2', 'mcq', 'general', 'What is the minimum number of characters for a new password?', to_jsonb(ARRAY['8','6','10','60']::text[]), '8', 'The notice states the password "must have at least 8 characters."', (SELECT id FROM passage2_3));
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag) VALUES
    ('Product Recall Notice: Model KX-200 Kettle', 'We have found a safety problem with the KX-200 electric kettle sold between March and May this year. The handle may become loose during use, which could cause the kettle to fall. If you own this model, please stop using it immediately. Check the bottom of your kettle for the model number. Customers can return the kettle to any store for a full refund, or contact our support line to arrange a free replacement part. This recall does not affect the KX-100 or KX-300 models. We apologise for any inconvenience and thank customers for their patience while we correct this issue.', 'reading', 'B1', 'general')
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'B1', 'mcq', 'general', 'What is the problem with the KX-200 kettle?', to_jsonb(ARRAY['The handle may become loose','The kettle may overheat','The power cord is damaged','The lid does not close']::text[]), 'The handle may become loose', 'The notice says "The handle may become loose during use, which could cause the kettle to fall."', (SELECT id FROM passage2_4)),
  ('reading', 'B1', 'mcq', 'general', 'What can customers do to get a full refund?', to_jsonb(ARRAY['Return the kettle to any store','Call the factory','Send the kettle by post','Visit the website']::text[]), 'Return the kettle to any store', 'The notice states customers "can return the kettle to any store for a full refund."', (SELECT id FROM passage2_4)),
  ('reading', 'B1', 'mcq', 'general', 'Which models are NOT affected by this recall?', to_jsonb(ARRAY['KX-100 and KX-300','KX-200 and KX-300','Only KX-100','All kettle models']::text[]), 'KX-100 and KX-300', 'The notice says "This recall does not affect the KX-100 or KX-300 models"; the KX-200 is the affected model.', (SELECT id FROM passage2_4));
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag) VALUES
    ('Welcome as a New Supplier', 'Subject: Welcome as a New Supplier
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'B1', 'mcq', 'email', 'How many documents does the supplier need to send?', to_jsonb(ARRAY['Three','Two','Five','Four']::text[]), 'Three', 'The email says "we need three documents from you: a copy of your business licence, your bank details for payment, and proof of insurance."', (SELECT id FROM passage2_5)),
  ('reading', 'B1', 'mcq', 'email', 'What are the company''s standard payment terms?', to_jsonb(ARRAY['30 days from the invoice date','30 days from the order date','14 days from delivery','Payment in advance']::text[]), '30 days from the invoice date', 'The email states "Our standard payment terms are 30 days from the invoice date."', (SELECT id FROM passage2_5)),
  ('reading', 'B1', 'mcq', 'email', 'Who should the supplier contact with questions about the process?', to_jsonb(ARRAY['Ms. Lund','Mr. Osei','the procurement team''s general email','the finance department']::text[]), 'Ms. Lund', 'The email says to "contact our procurement manager, Ms. Lund, directly"; Mr. Osei is the supplier receiving the email, not the contact.', (SELECT id FROM passage2_5));
