    ('Launch of the Employee Wellness Programme', 'Memo: Launch of the Employee Wellness Programme
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'B2', 'mcq', 'general', 'What percentage of gym fees does the company subsidise?', to_jsonb(ARRAY['50%','100%','25%','75%']::text[]), '50%', 'The memo mentions "a subsidised gym membership covering 50% of monthly fees at partner gyms."', (SELECT id FROM passage2_6)),
  ('reading', 'B2', 'mcq', 'general', 'How should employees join the yoga sessions?', to_jsonb(ARRAY['Register with the HR team','Sign up at the gym','Call the counselling helpline','Speak to their manager']::text[]), 'Register with the HR team', 'The memo says employees "should register with the HR team" to join the yoga sessions.', (SELECT id FROM passage2_6)),
  ('reading', 'B2', 'mcq', 'general', 'What does the memo say about taking short breaks during the day?', to_jsonb(ARRAY['It is encouraged by managers but is not a formal part of the programme','It is a required daily activity','It replaces the yoga sessions','It is only available to managers']::text[]), 'It is encouraged by managers but is not a formal part of the programme', 'The memo states this is "encouraged" by managers but "is not a formal element of the programme."', (SELECT id FROM passage2_6));
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag) VALUES
    ('Registration Confirmed – Annual Sales Conference', 'Subject: Registration Confirmed – Annual Sales Conference
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'B2', 'mcq', 'email', 'What happens to workshop places if delegates wait too long to select them?', to_jsonb(ARRAY['Places may already be taken because they are allocated first-come, first-served','Extra workshops will be added automatically','Places are guaranteed regardless of registration date','Workshops will be cancelled']::text[]), 'Places may already be taken because they are allocated first-come, first-served', 'The email states "workshop places are allocated on a first-come, first-served basis."', (SELECT id FROM passage2_7)),
  ('reading', 'B2', 'mcq', 'email', 'Who can receive a certificate of attendance?', to_jsonb(ARRAY['Only delegates who attend both days in full','Any delegate who requests one','Only keynote speakers','Delegates who attend at least one day']::text[]), 'Only delegates who attend both days in full', 'The email says the certificate "will only be issued to delegates who attend both days in full."', (SELECT id FROM passage2_7)),
  ('reading', 'B2', 'mcq', 'email', 'What happens if a delegate cancels after 1 September?', to_jsonb(ARRAY['No refund is given, but a substitute delegate may attend free of charge','A full refund is given automatically','A 50% refund is given','The delegate loses their badge but gets a refund']::text[]), 'No refund is given, but a substitute delegate may attend free of charge', 'The email states that after 1 September "no refunds can be given, although substitute delegates are welcome at no extra charge."', (SELECT id FROM passage2_7));
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag) VALUES
    ('Company-wide Rollout of the New Expense Management System', 'Following a successful pilot in the finance department, the new expense management system, ExpensePro, will be rolled out to all departments over the coming month. Staff will be migrated in three phases, beginning with Sales and Marketing next week, followed by Operations two weeks later, and finally Customer Support and HR in the final phase. Each department will receive a 45-minute training session prior to go-live, and a dedicated support channel will be available on the intranet throughout the transition period. Employees are asked to submit any expense claims currently in progress through the existing system before their department''s cut-off date, as claims cannot be transferred between systems once migration is complete. Early feedback from the pilot group has been largely positive, with users particularly welcoming the mobile receipt-scanning feature, although several noted that the approval workflow for claims over £500 still requires a manual signature, a limitation the IT team is working to address in a future update. Managers should encourage their teams to complete the mandatory training before their go-live date, as access to the new system will not be granted otherwise.', 'reading', 'C1', 'general')
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'C1', 'mcq', 'general', 'Which department will be migrated to ExpensePro first, according to the rollout schedule?', to_jsonb(ARRAY['Sales and Marketing','Operations','Finance','Customer Support and HR']::text[]), 'Sales and Marketing', 'The text says migration begins "with Sales and Marketing next week"; Finance was already using the system as the pilot department.', (SELECT id FROM passage2_8)),
  ('reading', 'C1', 'mcq', 'general', 'According to early feedback, what limitation of the system have some users noted?', to_jsonb(ARRAY['Claims over £500 still require a manual signature','The mobile app cannot scan receipts','The system does not work on the intranet','Training sessions are too short']::text[]), 'Claims over £500 still require a manual signature', 'The text notes users found "the approval workflow for claims over £500 still requires a manual signature."', (SELECT id FROM passage2_8)),
  ('reading', 'C1', 'mcq', 'general', 'What must employees do before their department''s cut-off date?', to_jsonb(ARRAY['Submit any in-progress expense claims through the existing system','Complete their mandatory training','Download the ExpensePro mobile app','Request manager approval for all claims']::text[]), 'Submit any in-progress expense claims through the existing system', 'The text says employees must submit in-progress claims "before their department''s cut-off date, as claims cannot be transferred between systems once migration is complete."', (SELECT id FROM passage2_8));
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag) VALUES
    ('Understanding the New Performance Review Cycle', 'This year, the company is moving from a single annual performance review to a continuous feedback model, in which employees and managers hold shorter, more frequent check-ins every quarter. The change follows staff survey findings suggesting that annual reviews often felt disconnected from day-to-day work and left little room to address concerns before they became significant. Under the new model, each quarterly check-in focuses on progress toward goals set at the start of the year, with formal ratings still assigned only once, at the year-end review. This means that while feedback will be ongoing, the rating that determines eligibility for bonuses and promotions is not finalised until December. Employees are encouraged to keep a running record of achievements throughout the year, as managers will draw on notes from all four check-ins when preparing the year-end assessment, rather than relying solely on their most recent impression. HR has also introduced an optional peer-feedback component, allowing colleagues to contribute observations that managers may include in the review, though this input is advisory only and does not itself affect the final rating.', 'reading', 'C1', 'general')
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'C1', 'mcq', 'general', 'When is the formal performance rating assigned?', to_jsonb(ARRAY['Once, at the year-end review','At each quarterly check-in','Only if HR requests it','At the start of the year when goals are set']::text[]), 'Once, at the year-end review', 'The text says "formal ratings still assigned only once, at the year-end review."', (SELECT id FROM passage2_9)),
  ('reading', 'C1', 'mcq', 'general', 'Why did the company change its review process?', to_jsonb(ARRAY['Because annual reviews often felt disconnected from daily work and delayed addressing concerns','Because managers requested more paperwork','Because bonuses were being paid too often','Because peer feedback was made compulsory']::text[]), 'Because annual reviews often felt disconnected from daily work and delayed addressing concerns', 'The text states the change follows findings that annual reviews "often felt disconnected from day-to-day work and left little room to address concerns before they became significant."', (SELECT id FROM passage2_9)),
  ('reading', 'C1', 'mcq', 'general', 'What effect does peer feedback have on an employee''s final rating?', to_jsonb(ARRAY['It is advisory only and does not itself affect the final rating','It automatically determines 50% of the final rating','It replaces the manager''s assessment','It is used only for promotions, not ratings']::text[]), 'It is advisory only and does not itself affect the final rating', 'The text says peer feedback input "is advisory only and does not itself affect the final rating."', (SELECT id FROM passage2_9));
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag) VALUES
    ('From the CEO''s Desk: Reflections on a Turbulent Quarter', 'It would be disingenuous to pretend this quarter unfolded as smoothly as we''d hoped. The supply chain disruptions that dogged us through April forced several difficult calls, not least the temporary pause on our Nordic expansion, a decision I know landed poorly with the regional team who had spent months laying the groundwork. And yet, viewed against the wider picture, there is genuine cause for optimism. Revenue held broadly steady despite the headwinds, a testament less to any single masterstroke than to the quiet, unglamorous discipline shown across procurement and logistics, teams whose contributions rarely make it into these updates but without whom the quarter would have looked very different indeed. Looking ahead, the board has approved renewed investment in the Nordic plans, though timelines remain deliberately loose given how quickly circumstances have shifted this year. I would rather under-promise here than repeat the overconfidence that, if I am honest, coloured some of our earlier communications. What I can promise is candour: when things go well, we will say so, and when they do not, you will hear that too, plainly and without spin. Thank you, as ever, for the resilience you have shown these past months.', 'reading', 'C2', 'general')
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'C2', 'mcq', 'general', 'What does the CEO imply about the company''s past communications?', to_jsonb(ARRAY['They were sometimes overconfident','They were always accurate','They deliberately hid all problems','They were written by the board, not the CEO']::text[]), 'They were sometimes overconfident', 'The CEO admits wanting to avoid repeating "the overconfidence that... coloured some of our earlier communications."', (SELECT id FROM passage2_10)),
  ('reading', 'C2', 'mcq', 'general', 'What has happened to the Nordic expansion?', to_jsonb(ARRAY['It was paused and has now had renewed investment approved, though with loose timelines','It has been permanently cancelled','It was never affected by the supply chain disruptions','It was completed ahead of schedule']::text[]), 'It was paused and has now had renewed investment approved, though with loose timelines', 'The letter mentions "the temporary pause on our Nordic expansion" and that "the board has approved renewed investment in the Nordic plans, though timelines remain deliberately loose."', (SELECT id FROM passage2_10)),
  ('reading', 'C2', 'mcq', 'general', 'According to the CEO, what mainly explains the steady revenue this quarter?', to_jsonb(ARRAY['The consistent efforts of the procurement and logistics teams','A single major strategic decision by the board','The success of the Nordic expansion','Reduced spending on communications']::text[]), 'The consistent efforts of the procurement and logistics teams', 'The CEO credits steady revenue to "the quiet, unglamorous discipline shown across procurement and logistics," not "any single masterstroke."', (SELECT id FROM passage2_10));
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag) VALUES
    ('Customer Satisfaction Survey: Q2 Results Summary', 'This quarter''s survey drew a healthy response rate of 62%, up from 48% in Q1, though it''s worth noting that the increase coincided with a prize-draw incentive we hadn''t previously offered, so some caution is warranted before reading too much into the improved engagement alone. Overall satisfaction scores rose modestly to 7.8 out of 10, continuing a gradual upward trend since the service-desk restructuring in January. The most striking shift, however, was in the free-text comments: complaints about response times, which dominated Q1 feedback, fell sharply, while a new theme emerged around the clarity of billing statements, an area that had barely registered as an issue before. This suggests the January changes succeeded in addressing their intended target but may have inadvertently drawn attention to a problem that was previously overshadowed by more pressing concerns rather than genuinely worsening. Notably, satisfaction among customers who contacted support more than twice was markedly lower than among first-time contacts, hinting that our resolution process may still struggle with more complex or recurring issues even as it handles routine queries well. We recommend the billing team review statement design before Q3, while the support team should investigate repeat-contact cases specifically rather than treating overall satisfaction as the only relevant metric.', 'reading', 'C2', 'customer_service')
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('reading', 'C2', 'mcq', 'customer_service', 'Why does the report urge caution about the higher survey response rate?', to_jsonb(ARRAY['Because it may be linked to a new prize-draw incentive rather than genuinely greater engagement','Because the response rate actually fell','Because the survey was conducted differently in Q2','Because too few customers responded to be meaningful']::text[]), 'Because it may be linked to a new prize-draw incentive rather than genuinely greater engagement', 'The report notes the increase "coincided with a prize-draw incentive we hadn''t previously offered, so some caution is warranted."', (SELECT id FROM passage2_11)),
  ('reading', 'C2', 'mcq', 'customer_service', 'What does the report suggest about the new complaints regarding billing statement clarity?', to_jsonb(ARRAY['The issue likely existed before but was overshadowed by bigger concerns like response times','Billing statements were changed in January and became worse','Billing complaints have always been the top concern','The billing team caused the increase in response times']::text[]), 'The issue likely existed before but was overshadowed by bigger concerns like response times', 'The report says the billing issue was "previously overshadowed by more pressing concerns rather than genuinely worsening."', (SELECT id FROM passage2_11)),
  ('reading', 'C2', 'mcq', 'customer_service', 'What does the report say about customers who contacted support more than twice?', to_jsonb(ARRAY['Their satisfaction was markedly lower than first-time contacts, suggesting the process struggles with complex or recurring issues','They were the most satisfied group overall','They were excluded from the survey','Their satisfaction matched first-time contacts exactly']::text[]), 'Their satisfaction was markedly lower than first-time contacts, suggesting the process struggles with complex or recurring issues', 'The report states satisfaction among repeat contacts "was markedly lower than among first-time contacts, hinting that our resolution process may still struggle with more complex or recurring issues."', (SELECT id FROM passage2_11));
